content.text:
{
 "_comment": [
  "gh-1630 I2 \u2014 the vendor supply chain lock: every artifact the",
  "extension package carries is pinned to a URL + post-transform",
  "SHA-256. scripts/fetch_vendor_assets.sh fetches ONLY from this",
  "lock, applies the declared `replacements` (each must occur exactly",
  "once \u2014 that is how remote constants are stripped out of vendored",
  "bundles, e.g. pyodide's CDN default indexURL), verifies the",
  "checksum and fails the build loud on any mismatch. Binaries are",
  "build-time fetched, never committed (browser_ext/vendor/ is",
  "gitignored); the PACKAGE carries them, the repo carries the lock."
 ],
 "lock_version": 1,
 "engines": {
  "quickjs": {
   "version": "0.31.0",
   "files": [
    {
     "name": "interpreters/index.global.js",
     "url": "https://cdn.jsdelivr.net/npm/quickjs-emscripten@0.31.0/dist/index.global.js",
     "sha256": "326c4de4f53ddd7d1cc8b9bc8189d1c3b68906315e5439141f0409d9c01ef99a"
    },
    {
     "name": "interpreters/asyncify/emscripten-module.browser.mjs",
     "url": "https://cdn.jsdelivr.net/npm/@jitl/quickjs-wasmfile-release-asyncify@0.31.0/dist/emscripten-module.browser.mjs",
     "sha256": "45d2ce579cc5579179ed6f48bcd6372d0f2dbfeb65bf9fe3077bbb1db0762bc3"
    },
    {
     "name": "interpreters/asyncify/emscripten-module.wasm",
     "url": "https://cdn.jsdelivr.net/npm/@jitl/quickjs-wasmfile-release-asyncify@0.31.0/dist/emscripten-module.wasm",
     "sha256": "98d27ff5e8babbca4b28a7b9242f554cd51e758498d90b00638a4b1b36b6f463"
    },
    {
     "name": "interpreters/asyncify/ffi.mjs",
     "url": "https://cdn.jsdelivr.net/npm/@jitl/quickjs-wasmfile-release-asyncify@0.31.0/dist/ffi.mjs",
     "sha256": "ee9b6572d09cd71a3d7c3cb76025a8540ec0d2b57ad6df85568213357ed31838",
     "replacements": [
      [
       "from\"@jitl/quickjs-ffi-types\"",
       "from\"./ffi-types-shim.mjs\""
      ]
     ]
    }
   ]
  },
  "pyodide": {
   "version": "0.26.4",
   "files": [
    {
     "name": "interpreters/pyodide.js",
     "url": "https://cdn.jsdelivr.net/pyodide/v0.26.4/full/pyodide.js",
     "sha256": "4ca912d6a4c63813b007ff0e8666c914ad891b1702262321a9ec7639828699c7",
     "replacements": [
      [
       "https://cdn.jsdelivr.net/pyodide/v${d.version}/full/",
       "../../vendor/interpreters/"
      ]
     ]
    },
    {
     "name": "interpreters/pyodide.asm.js",
     "url": "https://cdn.jsdelivr.net/pyodide/v0.26.4/full/pyodide.asm.js",
     "sha256": "919560652ed3dad3707cb3a394785da1e046fb13dc0defa162058ff230cb7eed"
    },
    {
     "name": "interpreters/pyodide.asm.wasm",
     "url": "https://cdn.jsdelivr.net/pyodide/v0.26.4/full/pyodide.asm.wasm",
     "sha256": "b7e66a19427a55010ac3367c1b6c64b893f9826f783412945fdf0c3337f3bc94"
    },
    {
