        reason: 'gh-1551: the empty-schedule-tick pre-check gates every leg',
      );
      expect(
        cond,
        contains("needs.release-dedupe.outputs.dedupe != 'true'"),
        reason: 'gh-1625: the release-twin pre-check gates every leg',
      );
    });

